// libcdr's note on them: CorelDRAW stores only the palette, the index and the tint of a colour
// from its fixed palettes. These tables were made by clean-room reverse-engineering from the
// CMYK, RGB or L*a*b* values CorelDRAW shows, without colour names, so they can only turn an
// indexed colour into its components.

//! Inks of CorelDRAW's fixed palettes: (model, palette) to one row of components per colour.

/// What a palette's rows hold.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Kind {
    /// C, M, Y, K, 0..100.
    Cmyk,
    /// R, G, B.
    Rgb,
    /// L, a, b as CorelDRAW's L*a*b* model 0x12 stores them.
    Lab,
}

/// The rows of a fixed palette, and whether its colours are numbered from 0.
pub fn table(model: u16, palette: u16) -> Option<(Kind, bool, &'static [[u8; 4]])> {
    Some(match (model, palette) {
        (0x0e, 0x0c) => (Kind::Lab, false, &P0E_0C),
        (0x0e, 0x18) => (Kind::Lab, false, &P0E_18),
        (0x0e, 0x21) => (Kind::Lab, false, &P0E_21),
        (0x0e, 0x22) => (Kind::Lab, false, &P0E_22),
        (0x19, 0x03) => (Kind::Cmyk, false, &P19_03),
        (0x19, 0x08) => (Kind::Cmyk, false, &P19_08),
        (0x19, 0x09) => (Kind::Lab, false, &P19_09),
        (0x19, 0x0a) => (Kind::Cmyk, false, &P19_0A),
        (0x19, 0x0b) => (Kind::Cmyk, false, &P19_0B),
        (0x19, 0x11) => (Kind::Cmyk, false, &P19_11),
        (0x19, 0x12) => (Kind::Cmyk, false, &P19_12),
        (0x19, 0x14) => (Kind::Cmyk, false, &P19_14),
        (0x19, 0x15) => (Kind::Cmyk, false, &P19_15),
        (0x19, 0x16) => (Kind::Cmyk, false, &P19_16),
        (0x19, 0x17) => (Kind::Cmyk, false, &P19_17),
        (0x19, 0x1a) => (Kind::Cmyk, true, &P19_1A),
        (0x19, 0x1b) => (Kind::Cmyk, true, &P19_1B),
        (0x19, 0x1c) => (Kind::Cmyk, true, &P19_1C),
        (0x19, 0x1d) => (Kind::Cmyk, true, &P19_1D),
        (0x19, 0x1e) => (Kind::Rgb, false, &P19_1E),
        (0x19, 0x1f) => (Kind::Rgb, false, &P19_1F),
        (0x19, 0x20) => (Kind::Rgb, false, &P19_20),
        (0x19, 0x23) => (Kind::Cmyk, false, &P19_23),
        (0x19, 0x24) => (Kind::Cmyk, false, &P19_24),
        (0x19, 0x25) => (Kind::Cmyk, false, &P19_25),
        _ => return None,
    })
}

